SELECT COUNT(DISTINCT session_id) AS july_sessions
FROM sessions
WHERE session_start >= '2026-07-01' AND session_start < '2026-08-01';

SELECT COUNT(DISTINCT session_id) AS june_sessions
FROM sessions
WHERE session_start >= '2026-06-01' AND session_start < '2026-07-01';

SELECT COUNT(DISTINCT order_id) AS total_orders
FROM orders
WHERE order_date BETWEEN '2026-07-01' AND '2026-09-30';

SELECT COUNT(*) AS total_orders
FROM orders
WHERE order_date >= '2026-07-01' AND order_date <= '2026-09-30';

SELECT COUNT(*) AS bonus_count
FROM incentive_bonuses
WHERE team = 'Riverside' AND EXTRACT(YEAR FROM bonus_date) = 2026 AND EXTRACT(MONTH FROM bonus_date) = 7;
